import{_ as l,o as i,c as e,ae as t}from"./chunks/framework.RRduUuAx.js";const c=JSON.parse('{"title":"账单拆分说明","description":"","frontmatter":{},"headers":[],"relativePath":"v1/zh/guide/09-bill-split-guide.md","filePath":"v1/zh/guide/09-bill-split-guide.md"}'),r={name:"v1/zh/guide/09-bill-split-guide.md"};function o(h,a,d,n,s,u){return i(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="账单拆分说明" tabindex="-1">账单拆分说明 <a class="header-anchor" href="#账单拆分说明" aria-label="Permalink to &quot;账单拆分说明&quot;">​</a></h1><h2 id="_1-这是什么功能" tabindex="-1">1. 这是什么功能 <a class="header-anchor" href="#_1-这是什么功能" aria-label="Permalink to &quot;1. 这是什么功能&quot;">​</a></h2><p>当一笔消费同时包含多个用途（例如“超市购物”里既有水果也有日用品），可以把这一笔账单拆成多笔子账单，让分类统计更准确。</p><p>拆分完成后：</p><ul><li>您会看到多笔“子账单”（每笔有自己的分类、金额、备注）。</li><li>原始那笔账单会变成“拆分容器”，不再参与列表展示与统计汇总，避免金额重复计算。</li></ul><h2 id="_2-适用场景" tabindex="-1">2. 适用场景 <a class="header-anchor" href="#_2-适用场景" aria-label="Permalink to &quot;2. 适用场景&quot;">​</a></h2><ul><li>一笔付款包含多个类别（餐饮 + 日用品、交通 + 停车等）</li><li>需要更精细的分类统计、预算对比</li><li>同一张小票想拆给不同的分类/标签</li></ul><h2 id="_3-如何使用" tabindex="-1">3. 如何使用 <a class="header-anchor" href="#_3-如何使用" aria-label="Permalink to &quot;3. 如何使用&quot;">​</a></h2><ol><li>进入“账单列表”找到要拆分的账单</li><li>对该账单进行左滑操作，选择“拆分”</li><li>在“拆分账单”页面中： <ul><li>点击子项的“分类”选择需要的收支项</li><li>点击“金额”填写每个子项的金额</li><li>备注可选填（用于补充说明）</li><li>需要更多项时，点击“添加一项”</li></ul></li><li>确保“剩余待分配金额”为 0（表示子项合计刚好等于原始账单金额）</li><li>点击右上角“完成/保存”提交</li></ol><h2 id="_4-使用规则与注意事项" tabindex="-1">4. 使用规则与注意事项 <a class="header-anchor" href="#_4-使用规则与注意事项" aria-label="Permalink to &quot;4. 使用规则与注意事项&quot;">​</a></h2><ul><li>子项金额合计必须等于原始账单金额，否则无法保存。</li><li>每一条子项都需要选择分类，且金额必须大于 0。</li><li>拆分后的统计口径以子账单为准；原始账单不再计入统计。</li><li>拆分支持多级拆分：子账单也可以再次拆分；最终统计以最末级子账单为准。</li><li>拆分与报销互斥：已标记“可报销/待报销/已报销”的支出账单不能进行拆分；已拆分的账单也无法开启报销流程。建议先确定这笔支出是否需要走报销，再决定是否拆分。</li></ul><h2 id="_5-常见问题" tabindex="-1">5. 常见问题 <a class="header-anchor" href="#_5-常见问题" aria-label="Permalink to &quot;5. 常见问题&quot;">​</a></h2><h3 id="q1-拆分后原始账单去哪了" tabindex="-1">Q1：拆分后原始账单去哪了？ <a class="header-anchor" href="#q1-拆分后原始账单去哪了" aria-label="Permalink to &quot;Q1：拆分后原始账单去哪了？&quot;">​</a></h3><p>为了避免金额重复统计，原始账单会被标记为“拆分容器”，通常不会在列表中展示；实际统计会以拆分后的子账单为准。</p><h3 id="q2-能只拆一部分吗" tabindex="-1">Q2：能只拆一部分吗？ <a class="header-anchor" href="#q2-能只拆一部分吗" aria-label="Permalink to &quot;Q2：能只拆一部分吗？&quot;">​</a></h3><p>可以。您可以把其中一项保留为“其他/原分类”，金额填写为剩余金额即可。核心要求是所有子项金额合计等于原始金额。</p><h3 id="q3-拆分后还能改吗" tabindex="-1">Q3：拆分后还能改吗？ <a class="header-anchor" href="#q3-拆分后还能改吗" aria-label="Permalink to &quot;Q3：拆分后还能改吗？&quot;">​</a></h3><p>一般建议直接修改拆分后的子账单（金额/分类/备注等）。如果需要重新拆分，通常做法是先删除相关子账单再重新操作。</p>',18)])])}const p=l(r,[["render",o]]);export{c as __pageData,p as default};
